ALTER TABLE users ADD reputation INT NOT NULL DEFAULT 100, ADD message_privacy VARCHAR(20) NOT NULL DEFAULT 'following', ADD notify_unfollow BOOLEAN NOT NULL DEFAULT FALSE, ADD notify_mention BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE replies ADD quote_reply_id BIGINT NULL;
ALTER TABLE posts ADD attachment_path VARCHAR(255), ADD cover_path VARCHAR(255), ADD accepted_at DATETIME NULL, ADD featured_at DATETIME NULL;
CREATE TABLE follows (follower_id BIGINT NOT NULL, followee_id BIGINT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(follower_id,followee_id), INDEX(followee_id));
CREATE TABLE followed_tags (user_id BIGINT NOT NULL, tag_id BIGINT NOT NULL, PRIMARY KEY(user_id,tag_id), INDEX(tag_id));
CREATE TABLE user_blocks (user_id BIGINT NOT NULL, blocked_id BIGINT NOT NULL, PRIMARY KEY(user_id,blocked_id));
CREATE TABLE conversations (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_a_id BIGINT NOT NULL, user_b_id BIGINT NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_a_id,user_b_id));
CREATE TABLE conversation_settings (conversation_id BIGINT NOT NULL, user_id BIGINT NOT NULL, muted BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE messages (id BIGINT PRIMARY KEY AUTO_INCREMENT, conversation_id BIGINT NOT NULL, sender_id BIGINT NOT NULL, content TEXT NOT NULL, type VARCHAR(10) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(conversation_id,id));
CREATE TABLE mentions (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,target_type,target_id));
CREATE TABLE votes (id BIGINT PRIMARY KEY AUTO_INCREMENT, post_id BIGINT NOT NULL UNIQUE, multiple BOOLEAN NOT NULL DEFAULT FALSE, closes_at DATETIME NOT NULL, visibility VARCHAR(20) NOT NULL DEFAULT 'always');
CREATE TABLE vote_options (id BIGINT PRIMARY KEY AUTO_INCREMENT, vote_id BIGINT NOT NULL, label VARCHAR(100) NOT NULL);
CREATE TABLE vote_ballots (vote_id BIGINT NOT NULL, option_id BIGINT NOT NULL, user_id BIGINT NOT NULL, PRIMARY KEY(vote_id,option_id,user_id), INDEX(vote_id,user_id));
CREATE TABLE bounties (post_id BIGINT PRIMARY KEY, amount INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'open', recipient_id BIGINT NULL);
CREATE TABLE drafts (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, board_id BIGINT NULL, type VARCHAR(20) NOT NULL DEFAULT 'question', title VARCHAR(160) NOT NULL DEFAULT '', content TEXT NOT NULL, image_path VARCHAR(255), cover_path VARCHAR(255), attachment_path VARCHAR(255), tag_ids VARCHAR(255) NOT NULL DEFAULT '', scheduled_at DATETIME NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE post_revisions (id BIGINT PRIMARY KEY AUTO_INCREMENT, post_id BIGINT NOT NULL, editor_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(post_id,id));
CREATE TABLE reply_revisions (id BIGINT PRIMARY KEY AUTO_INCREMENT, reply_id BIGINT NOT NULL, editor_id BIGINT NOT NULL, content TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(reply_id,id));
CREATE TABLE reputation_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, actor_id BIGINT NULL, amount INT NOT NULL, balance_after INT NOT NULL, reason VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,id));
CREATE TABLE appeals (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, reason TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', handler_id BIGINT NULL, handle_note VARCHAR(500), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, handled_at DATETIME NULL, INDEX(status,id));
